def param_set(self, param_name, _value=None, **kwargs):
        """
        Setting parameter. if _value, we inject it directly. if not, we use all extra kwargs
        :param topic_name: name of the topic
        :param _value: optional value
        :param kwargs: each extra kwarg will be put in the value if structure matches
        :return:
        """
        if _value is None:
            _value = {}
            for k, v in kwargs.items():
                if k in self.param_schema[param_name]:
                    _value[k] = v
                else:
                    raise Exception("{} is not a valid param for {}".format(k, param_name))
        else:
            if type(_value) != dict:
                raise Exception("value must be a dict")

        self.param_schema[param_name] = _value

